// Design 21 - "Cyber": the cyberpunk look of the Upcoming events page (card look 16) and its matching popup.
// Ash-grey paper, black slashes, holographic glass panels, heavy condensed type.
// You do not edit this file. The look is switched on by FORCE_DESIGN = 21 in site/upcomingConfig.js (or add ?design=21 to the address).
// Colours and fonts are at the top of site/Cyber.css.
import { useId } from 'react';
import { FieldValue, Actions } from './teaserCore';
import PosterStage from './PosterStage';
import { Actions as PopupActions, Desc, Shell } from './popupParts';
import { useInView } from './ui';
import './Cyber.css';

const MINT = '#7CF2D4';
const RED = '#E8283E';

/* ---------- the picture: a slide deck cut in half by a blade ("the death of PPT") ---------- */
export function SlashDeck() {
  const u = useId().replace(/[^a-zA-Z0-9]/g, '');
  const id = (n) => `cy${n}${u}`;
  const ref = (n) => `url(#${id(n)})`;
  return (
    <svg className="cy-deck" viewBox="0 0 560 380" aria-hidden="true" focusable="false">
      <defs>
        <linearGradient id={id('g')} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#18525c" stopOpacity=".97" />
          <stop offset="1" stopColor="#0a2733" stopOpacity=".97" />
        </linearGradient>
        <linearGradient id={id('b')} gradientUnits="userSpaceOnUse" x1="404" y1="-30" x2="156" y2="410">
          <stop offset="0" stopColor={MINT} stopOpacity="0" />
          <stop offset=".24" stopColor={MINT} />
          <stop offset=".5" stopColor="#ffffff" />
          <stop offset=".76" stopColor={MINT} />
          <stop offset="1" stopColor={MINT} stopOpacity="0" />
        </linearGradient>
        <linearGradient id={id('fl')} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor={MINT} stopOpacity="0" />
          <stop offset="1" stopColor={MINT} stopOpacity=".16" />
        </linearGradient>
        <filter id={id('f')} x="-80%" y="-10%" width="260%" height="120%">
          <feGaussianBlur stdDeviation="3.2" result="b" />
          <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
        </filter>
        <clipPath id={id('a')}><polygon points="-60,-60 404,-60 156,430 -60,430" /></clipPath>
        <clipPath id={id('c')}><polygon points="404,-60 620,-60 620,430 156,430" /></clipPath>

        <g id={id('s')}>
          <rect x="108" y="48" width="326" height="232" rx="9" transform="rotate(-8 271 164)" fill="none" stroke={MINT} strokeOpacity=".26" />
          <rect x="126" y="60" width="326" height="232" rx="9" transform="rotate(-3.5 289 176)" fill="#0a2733" fillOpacity=".72" stroke={MINT} strokeOpacity=".42" />
          <rect x="146" y="76" width="326" height="232" rx="9" fill={ref('g')} stroke={MINT} strokeOpacity=".8" />
          <rect x="146" y="76" width="326" height="28" rx="9" fill={MINT} fillOpacity=".14" />
          <rect x="146" y="94" width="326" height="10" fill={MINT} fillOpacity=".14" />
          <circle cx="164" cy="90" r="4" fill={RED} />
          <circle cx="178" cy="90" r="4" fill={MINT} fillOpacity=".5" />
          <circle cx="192" cy="90" r="4" fill={MINT} fillOpacity=".5" />
          <rect x="170" y="126" width="176" height="17" rx="3" fill={MINT} fillOpacity=".95" />
          <rect x="170" y="152" width="96" height="7" rx="3.5" fill={MINT} fillOpacity=".4" />
          <rect x="170" y="182" width="138" height="7" rx="3.5" fill="#fff" fillOpacity=".32" />
          <rect x="170" y="200" width="112" height="7" rx="3.5" fill="#fff" fillOpacity=".32" />
          <rect x="170" y="218" width="150" height="7" rx="3.5" fill="#fff" fillOpacity=".32" />
          <rect x="170" y="236" width="90" height="7" rx="3.5" fill="#fff" fillOpacity=".32" />
          <rect x="344" y="176" width="100" height="84" rx="4" fill="#000" fillOpacity=".22" stroke={MINT} strokeOpacity=".3" />
          <rect x="356" y="222" width="12" height="28" fill={MINT} fillOpacity=".8" />
          <rect x="374" y="206" width="12" height="44" fill={MINT} fillOpacity=".8" />
          <rect x="392" y="192" width="12" height="58" fill="#fff" fillOpacity=".85" />
          <rect x="410" y="214" width="12" height="36" fill={MINT} fillOpacity=".8" />
          <rect x="428" y="200" width="8" height="50" fill={MINT} fillOpacity=".5" />
          <text x="170" y="290" className="cy-svg-t">DECK.PPTX</text>
          <text x="444" y="290" className="cy-svg-t" textAnchor="end">10 / 10</text>
        </g>
      </defs>

      <g opacity=".5">
        <rect x="0" y="262" width="560" height="118" fill={ref('fl')} />
        {[286, 306, 330, 360].map((y) => <line key={y} x1="0" y1={y} x2="560" y2={y} stroke={MINT} strokeOpacity=".16" />)}
        {[-120, 20, 140, 240, 280, 320, 420, 540, 680].map((x) => <line key={x} x1="280" y1="262" x2={x} y2="380" stroke={MINT} strokeOpacity=".14" />)}
      </g>

      <g className="cy-half a"><g clipPath={ref('a')}><use href={`#${id('s')}`} /></g></g>
      <g className="cy-half b"><g clipPath={ref('c')}><use href={`#${id('s')}`} /></g></g>

      <line className="cy-blade-glow" x1="404" y1="-30" x2="156" y2="410" stroke={ref('b')} strokeWidth="10" opacity=".3" />
      <line className="cy-blade" x1="404" y1="-30" x2="156" y2="410" stroke={ref('b')} strokeWidth="2.6" filter={ref('f')} pathLength="1" />

      <g className="cy-shards">
        <polygon className="cy-shard s1" points="318,150 336,144 330,160" fill={MINT} />
        <polygon className="cy-shard s2" points="262,236 282,232 274,250" fill="#fff" />
        <polygon className="cy-shard s3" points="214,306 228,300 226,316" fill={MINT} />
        <polygon className="cy-shard s4" points="352,84 364,82 358,94" fill="#fff" />
        <polygon className="cy-shard s5" points="190,352 204,346 200,360" fill={MINT} />
        <polygon className="cy-shard s6" points="296,196 306,200 298,208" fill={RED} />
      </g>

      <text x="22" y="34" className="cy-svg-h">$ rm -rf slides/</text>
      <text x="22" y="340" className="cy-svg-h">$ ship --live<tspan className="cy-svg-cur">_</tspan></text>
    </svg>
  );
}

/* ---------- the event name: black type that gets cut by a slash ---------- */
function CyTitle({ text, as: Tag = 'h2', ...rest }) {
  const longest = Math.max(6, ...String(text).split(/\s+/).map((w) => w.length));
  return (
    <Tag {...rest} className={`cy-title ${rest.className || ''}`.trim()} aria-label={text} style={{ '--n': longest }}>
      <span className="cy-tt" aria-hidden="true">
        <span className="cy-ta">{text}</span>
        <span className="cy-tb">{text}</span>
        <i className="cy-cut" />
      </span>
    </Tag>
  );
}

const Stripes = () => <span className="cy-stripes" aria-hidden="true"><i /><i /><i /></span>;

/* a panel of holographic glass (the double clip draws the thin border on the cut corners too) */
function Panel({ title, tone = '', className = '', children }) {
  return (
    <div className={`cy-pw ${className}`}>
      <section className={`cy-panel ${tone}`}>
        <div className="cy-pin">
          <header className="cy-ph"><span>{title}</span><i /><i /><i /></header>
          {children}
        </div>
      </section>
    </div>
  );
}

const pad = (v) => (typeof v === 'number' ? String(v).padStart(2, '0') : v);
const SEG = 24;

/* ---------- the card on the Upcoming events page (look 16) ---------- */
export function CyberCard({ t }) {
  const { copy } = t;
  const [ref, seen] = useInView(0.2);
  const name = t.name || 'Classified';
  return (
    <article ref={ref} className={`cy t-${t.type} is-${t.phase} ${seen ? 'is-in' : ''}`} aria-label={t.label}>
      <div className="cy-bg" aria-hidden="true">
        <i className="cy-paper" /><i className="cy-grain" />
        <i className="cy-bl b1" /><i className="cy-bl b2" /><i className="cy-bl b3" /><i className="cy-bl b4" /><i className="cy-bl b5" />
        <i className="cy-x x1" /><i className="cy-x x2" /><i className="cy-x x3" /><i className="cy-x x4" /><i className="cy-x x5" />
        <i className="cy-frame" />
      </div>

      <div className="cy-grid">
        <div className="cy-main">
          <span className="cy-flag"><Stripes />{copy.flag}</span>
          <CyTitle text={name} />
          <p className="cy-lede"><span>{copy.lede}</span></p>
          <p className="cy-desc">{copy.desc}</p>

          <div className="cy-fields">
            {t.fields.map((f) => (
              <div key={f.k} className={`cy-f is-${f.state}`}>
                <span className="cy-k">{f.k}</span>
                <b className="cy-v"><FieldValue f={f} /></b>
              </div>
            ))}
          </div>

          <Actions t={t} />
        </div>

        <div className="cy-holo">
          <Panel title="Live feed" className="p1">
            <div className="cy-art">
              <PosterStage kind="card" cap={340}><SlashDeck /></PosterStage>
            </div>
          </Panel>

          <Panel title="Countdown" tone="is-warm" className="p2">
            {t.live ? (
              <div className="cy-live"><i /> It&apos;s live</div>
            ) : (
              <>
                <div
                  className={`cy-cd ${t.waiting ? 'is-idle' : ''}`}
                  role={t.counting ? 'timer' : 'group'}
                  aria-label={t.counting ? `${t.cdLabel} ${t.c.d} days ${t.c.h} hours ${t.c.m} minutes` : t.ended ? t.cdWait : 'Timer not started yet'}
                >
                  {t.cells.map(([n, v]) => (
                    <div className="cy-cell" key={n}>
                      <b key={v}>{pad(v)}</b>
                      <span>{n}</span>
                    </div>
                  ))}
                </div>
                <p className={`cy-cdn ${t.counting ? 'is-on' : ''}`}>{t.counting ? t.cdLabel : t.cdWait}</p>
              </>
            )}
          </Panel>

          <Panel title="Compile" className="p3">
            <div className="cy-prog" role="progressbar" aria-label="Compiling" aria-valuemin={0} aria-valuemax={100} aria-valuenow={t.shown}>
              <div className="cy-seg" aria-hidden="true">
                {Array.from({ length: SEG }, (_, i) => <i key={i} className={i < Math.round((t.shown / 100) * SEG) ? 'on' : ''} />)}
              </div>
              <div className="cy-pt"><span>{t.status}</span><b>{t.shown}%</b></div>
            </div>
          </Panel>
        </div>
      </div>
    </article>
  );
}

/* ---------- the popup ("Something big is coming") ---------- */
export function CyberPopup({ text, ...p }) {
  const title = text.name ? `${text.name} ${text.rest || ''}`.trim() : text.title;
  return (
    <Shell name="cyber" extra="pq" p={p}>
      <div className="cy-pp-bg" aria-hidden="true"><i className="cy-bl b1" /><i className="cy-bl b2" /><i className="cy-x x1" /><i className="cy-x x2" /></div>
      <div className="cy-pp-art">
        <PosterStage kind="popup"><SlashDeck /></PosterStage>
      </div>
      <div className="pp-body">
        <span className="cy-flag"><Stripes />{text.flag}</span>
        <CyTitle as="h2" id="s-ann-t" text={title} className="cy-pp-title" />
        <Desc text={text} />
        <PopupActions text={text} p={p} />
      </div>
    </Shell>
  );
}

export default CyberCard;
